 inventory[ident]={'original_source':a['record']['source_url'],'listed_versions':versions.get(ident,{}),'local_original_latest_pdf':'http/'+ident+'.pdf','local_original_latest_text':'http/'+ident+'.txt','version_files':[str(p.relative_to(L)) for p in sorted((L/'http').glob(ident+'-*.pdf'))],'actual_read_depth':depth,'scope_limits':out[ident]['review_depth']}
